const C={...window.SITE_CONFIG};C.legalName=C.legalName||C.siteName;['disclaimer','copyright','browserTitle','footerDisclaimer'].forEach(k=>C[k]=(C[k]||C.disclaimer).replaceAll('{{siteName}}',C.siteName));
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const I=n=>`<i data-lucide="${n}" aria-hidden="true"></i>`;
const img=(n,alt='',cl='')=>`<img src="assets/images/${n}.${(n.startsWith('r8-')||n.startsWith('compare-'))?'avif':'webp'}" alt="${alt}" class="${cl}" width="1400" height="933" loading="lazy">`;
const art=n=>`<img src="assets/images/${n}.webp" alt="" class="cutout ${n}" width="700" height="700" loading="lazy">`;
const btn=(url,t,cl='')=>`<a href="${url}" class="btn ${cl}"><span>${t}</span>${I('arrow-up-right')}</a>`;
const services=[{id:'water-extraction',name:'Water extraction',icon:'waves',key:'extract'},{id:'structural-drying',name:'Structural drying',icon:'fan',key:'dry'},{id:'damage-restoration',name:'Damage restoration',icon:'paint-roller',key:'restore'}];
const route=location.pathname.split('/').pop().replace('.html','')||'index',svc=services.find(x=>x.id===route);
function brand(){return `<a class="brand" href="index.html" aria-label="${esc(C.siteName)} home"><img src="${esc(C.logo)}" width="54" height="54" alt=""><span>${esc(C.siteName)}<small>WATER DAMAGE NETWORK</small></span></a>`}
function header(){return `<header><div class="container head-inner"><button class="menu-open icon-btn" aria-label="Open menu" aria-controls="site-menu" aria-expanded="false">${I('menu')}</button>${brand()}<nav class="desktop-nav"><a href="index.html">Home</a><a href="index.html#about">About us</a><div class="nav-drop"><a href="index.html#service-explorer">Services ${I('chevron-down')}</a><div>${services.map(s=>`<a href="${s.id}.html">${s.name}</a>`).join('')}</div></div><a href="contact.html">Contact</a></nav><button class="search-open icon-btn" aria-label="Search website">${I('search')}</button>${btn('contact.html','Start a conversation','small-btn')}</div></header><dialog id="site-menu"><div class="menu-head">${brand()}<button class="menu-close icon-btn" aria-label="Close menu">${I('x')}</button></div><div class="menu-center"><p class="menu-caption">A CLEARER WAY FORWARD</p><nav><a href="index.html">Home</a><a href="index.html#about">About us</a>${services.map(s=>`<a href="${s.id}.html">${s.name}</a>`).join('')}<a href="contact.html">Contact</a></nav><button class="search-open menu-search">${I('search')} Find a page or an idea</button><a class="email" href="mailto:${esc(C.email)}">${esc(C.email)}</a></div><div class="menu-water">${art('drops')}</div><div class="menu-bottom"><a href="privacy.html">Privacy</a><a href="terms.html">Terms</a><a href="cookies.html">Cookies</a></div></dialog><dialog id="search-dialog"><div class="search-water" aria-hidden="true">${art('v6-water-beads')}${art('v6-water-splash')}</div><div class="dialog-title"><h2>Find your next step.</h2><button class="search-close icon-btn" aria-label="Close search">${I('x')}</button></div><label class="search-input">${I('search')}<input type="search" id="search-input" placeholder="Services, materials, pricing…" aria-label="Search the website"></label><div id="results" aria-live="polite"></div></dialog>`}
function footer(){return `<footer><div class="container"><div class="footer-top">${brand()}<div><span>Every space deserves</span><strong>a fresh beginning.</strong></div><a href="mailto:${esc(C.email)}" class="email">${esc(C.email)}</a></div><div class="footer-middle"><p class="footer-disclaimer"><strong>Independent by design.</strong>${esc(C.footerDisclaimer)}</p><nav>${services.map(s=>`<a href="${s.id}.html">${s.name}</a>`).join('')}<a href="index.html#about">About us</a><a href="contact.html">Contact</a></nav></div><div class="footer-bottom"><span>${esc(C.copyright)}</span><nav><a href="privacy.html">Privacy</a><a href="terms.html">Terms</a><a href="cookies.html">Cookies</a><button class="cookie-settings">Cookie settings</button><a href="terms.html#credits">Icon credits</a></nav></div></div></footer><aside class="cookie-note" aria-label="Cookie preferences"><div>${I('cookie')}<span>Your privacy, your choice.<small>Essential storage only. No tracking.</small></span></div><a href="cookies.html">Details</a><button data-consent="essential">Essential only</button><button data-consent="accept">Accept</button></aside><div class="page-loader" aria-hidden="true">${art('drops')}<span>A fresh beginning.</span></div>`}
function section(id,cl,body){return `<section id="${id}" class="section ${cl}"><div class="container">${body}</div></section>`}
function heading(t,p='',center=false){return `<div class="section-heading ${center?'center':''}"><h2 class="reveal">${t}</h2>${p?`<p>${p}</p>`:''}</div>`}
function water(){return `<div class="water-seam" aria-hidden="true"><div class="container">${art('v6-water-edge')}</div></div>`}
const heroes={index:['A fresh start.<br><span>After water.</span>','Independent guidance for the spaces that matter. Explore water damage services and find your way forward.','home', 'Explore your options'], 'water-extraction':['Clear the water.<br><span>Keep moving.</span>','From flooded lower levels to affected living spaces. Begin with a clearer picture of water extraction.','extract','Discuss your space'], 'structural-drying':['Dry deeper.<br><span>Move forward.</span>','Understand the materials, moisture and questions behind a considered structural drying plan.','dry','Explore drying options'], 'damage-restoration':['Room to recover.<br><span>A fresh start.</span>','Floors, walls and the finishing touches. Explore the possibilities after the water has gone.','restore','Plan your next step'], contact:['Let’s talk.<br><span>About your space.</span>','A little context makes a better conversation. Tell us what happened and where you would like to begin.','contact','Write your enquiry']};
function hero(key){const a=heroes[key];return `<section class="hero hero-${a[2]}"><div class="container hero-inner"><div class="hero-copy"><span class="hero-label">${key==='index'?'WATER DAMAGE. A NEW PERSPECTIVE.':key==='contact'?'YOUR NEXT CHAPTER STARTS HERE':svc.name.toUpperCase()}</span><h1>${a[0]}</h1><p>${a[1]}</p><div class="hero-actions">${btn(key==='contact'?'#enquiry':key==='index'?'#service-explorer':'contact.html?service='+key,a[3])}${btn(key==='index'?'contact.html':key==='contact'?'mailto:'+esc(C.email):(key==='water-extraction'?'#extraction-in-context':key==='structural-drying'?'#materials-and-moisture':'#a-considered-repair'),key==='index'?'Let’s talk':key==='contact'?'Email us':'A closer look','outline')}</div><div class="hero-foot">${I('waypoints')} Independent providers. Informed choices.</div></div><div class="hero-visual" data-hero="${a[2]}"><div class="hero-image"><img src="assets/images/hero-${a[2]}-1.avif" alt="Water damage specialist in a distinctive modern interior" width="1400" height="933" fetchpriority="high"><div class="fragment-layer" aria-hidden="true"></div></div><div class="hero-slash slash-one"></div><div class="hero-slash slash-two"></div><div class="hero-slash slash-three"></div><div class="hero-controls"><button data-hero-prev aria-label="Previous photograph">${I('arrow-left')}</button><button class="hero-pause" aria-label="Pause changing photographs">${I('pause')}</button><button data-hero-next aria-label="Next photograph">${I('arrow-right')}</button></div><span class="hero-image-label">A NEW PERSPECTIVE ON YOUR SPACE</span></div></div></section>`}
function marquee(){return `<div class="marquee"><div>${Array.from({length:4},()=>['Assess','Extract','Dry','Restore'].map((x,i)=>`<span>${x}</span><img src="assets/icons/${['3242644','2875963','645674','6183144'][i]}.png" alt="" width="40" height="40">`).join('')).join('')}</div></div>`}
function slider(items,id,mode='photo'){return `<div class="slider-shell mode-${mode}"><div class="swiper" id="${id}"><div class="swiper-wrapper">${items.map((x,i)=>`<article class="swiper-slide ${mode==='service'?'offer-card':'portfolio-card'}">${mode==='service'?`<span class="card-icon">${I(i===3?'scan-line':services[i%3].icon)}</span><div class="offer-copy"><h3>${x[1]}</h3><p>${x[2]}</p></div>${img(x[0],x[1])}<a class="card-action" href="${i===3?'contact':services[i%3].id}.html" aria-label="Explore ${x[1]}">${I('arrow-up-right')}</a>`:`${img(x[0],x[1])}<div class="portfolio-caption"><span>${x[3]||'A CLOSER LOOK'}</span><h3>${x[1]}</h3><p>${x[2]}</p></div>`}</article>`).join('')}</div></div><div class="slider-controls"><button class="prev icon-btn" data-slider="${id}" aria-label="Previous slide">${I('arrow-left')}</button><div class="slider-progress" aria-hidden="true"><span></span></div><button class="next icon-btn" data-slider="${id}" aria-label="Next slide">${I('arrow-right')}</button></div></div>`}
function compare(key){return `<div class="compare-frame" data-compare style="--split:48%"><div class="compare-top"><span>${I('move-horizontal')} A DIFFERENT OUTLOOK</span><div><button data-split="22">Before</button><button data-split="78">After</button></div></div><div class="compare-stage">${img('compare-'+key+'-after','Illustrative repaired space','compare-after')}<div class="compare-before">${img('compare-'+key+'-before','The same illustrative space with water damage')}</div><div class="compare-line"><span>${I('chevrons-left-right')}</span></div><input type="range" min="0" max="100" value="48" aria-label="Compare the space before and after"></div><div class="compare-bottom"><span>One space. A whole new feeling.</span><small>Illustrative visualisation · drag to explore</small></div></div>`}
function faq(items){return `<div class="faq">${items.map(([q,a],i)=>`<details ${i===0?'open':''}><summary><span>${q}</span><b>${I('plus')}</b></summary><div class="answer"><p>${a}</p></div></details>`).join('')}</div>`}
function cta(person='worker',t='A clearer next step.'){return section('next-step','cta-section',`<div class="cta-card"><div><h2>${t}</h2><p>Tell us about the space. Start a more useful conversation.</p>${btn('contact.html','Let’s talk about it','white-btn')}</div><span class="cta-droplets" aria-hidden="true">${art('v6-water-beads')}${art('v6-water-splash')}</span>${art(person)}<span class="cta-outline" aria-hidden="true"></span><span class="cta-water" aria-hidden="true">${art('v6-water-edge')}</span></div>`)}
function home(){return hero('index')+water()+section('about','about-section',`<div class="mosaic-about"><div class="mosaic"><div>${img('editorial-1','Specialist checking moisture in a concrete interior')}</div><div>${img('editorial-2','Careful assessment of a terrazzo floor')}</div><div>${img('editorial-3','Ceiling detail after rainwater entry')}</div><div>${img('editorial-13','Surveyor discussing an affected space')}</div><span class="mosaic-square sq1"></span><span class="mosaic-square sq2"></span></div><div class="about-copy"><h2 class="reveal">A calmer way<br>to move forward.</h2><p class="lead">Your home is more than the damage. Let’s start with the bigger picture.</p><p>${esc(C.siteName)} brings clarity to the first conversation. Explore the services, consider the materials and prepare an enquiry for independent restoration providers.</p><div class="tick-grid"><span>${I('check')} Understand your options</span><span>${I('check')} Ask better questions</span><span>${I('check')} Define your priorities</span><span>${I('check')} Choose independently</span></div>${btn('contact.html','More clarity starts here','outline')}</div></div>`)+refServices()+section('spaces','takeover-section',heading('Every space tells a story.','Move across the photographs to explore a different perspective.')+`<div class="takeover" data-takeover><div class="takeover-backdrop"></div>${[['r8-space-1','Living spaces','Where everyday life takes place.'],['r8-space-2','At the edges','Joints, frames and the paths water follows.'],['r8-space-3','Underfoot','Materials that bring the room together.'],['r8-space-4','Beyond the finish','Look a little deeper than the visible surface.']].map(([im,t,p])=>`<button class="takeover-panel" data-photo="${im}">${img(im,t)}<span><strong>${t}</strong><small>${p}</small>${I('arrow-up-right')}</span></button>`).join('')}</div>`)+homeCircle()+section('pricing','pricing-section mist',`<div class="pricing-layout"><div><h2 class="reveal">Clarity.<br>Before commitment.</h2><p>Every space is different. Compare the scope of a quote, not just the total.</p></div><div class="quote-ticket"><span class="ticket-icon">${I('message-square')}</span><div><h3>Start a conversation</h3><p>No platform enquiry fee. Describe the space and explore the relevant service.</p><a href="contact.html">Prepare an enquiry ${I('arrow-up-right')}</a></div></div><div class="quote-ticket"><span class="ticket-icon">${I('clipboard-list')}</span><div><h3>A tailored quote</h3><p>Assessment and restoration costs are agreed directly with your chosen provider.</p><a href="contact.html">Discuss your scope ${I('arrow-up-right')}</a></div></div></div>`)+section('your-perspective','tabs-section',heading('A little context. A lot of clarity.','A better enquiry begins with the right details.',true)+tabs('home',[['Your space','editorial-11','See the whole picture.','Describe the rooms, materials and visible changes. Include what you know about the source and when you first noticed the issue.',['Affected rooms','Visible moisture','Access and layout']],['Your priorities','editorial-14','Start with what matters.','Tell a provider what you would like to understand. Ask about retained materials, the order of work and the effect on everyday use.',['Material condition','Scope of assessment','Your questions']],['Your next step','editorial-15','Agree on the details.','Discuss assessment charges, a written scope and the evidence needed to progress from drying into repair.',['Itemised quotation','Clear exclusions','Direct agreement']]]))+section('before-after','comparison-section',compare('home'))+pillProcess()+homeVoices()+newSections('home').slice(0,2).join('')+homeCollage()+newSections('home').slice(2).join('')+section('questions','faq-section',`<div class="faq-layout"><div class="faq-editorial"><h2 class="reveal">Good questions.<br>Clearer beginnings.</h2><p>Understand the platform before taking your next step.</p>${img('editorial-16','Restoration specialist considering the details of a room')}</div>${faq([['Do you carry out restoration work?',`${esc(C.siteName)} is an independent discovery platform. Your chosen provider carries out assessment, quotations and any agreed work.`],['Where should I begin?','Explore extraction for standing water, structural drying for retained moisture, and restoration for damaged finishes. A property-specific assessment can clarify where these overlap.'],['Can I get an exact price here?','Prices depend on the space and agreed scope. Ask an independent provider about assessment charges and request a written quote.'],['What belongs in my enquiry?','Describe the room, the timing, the visible changes and affected materials. Include the questions you would like a provider to address.']])}</div>`)+cta()+marquee()}
function tabs(id,data){return `<div class="tabs-widget" data-tabs="${id}"><div class="tab-list" role="tablist">${data.map((x,i)=>`<button role="tab" id="${id}-tab-${i}" aria-controls="${id}-panel-${i}" aria-selected="${i===0}" data-tab="${i}">${x[0]}</button>`).join('')}</div>${data.map((x,i)=>`<div class="tab-panel ${i===0?'active':''}" id="${id}-panel-${i}" role="tabpanel" aria-labelledby="${id}-tab-${i}" ${i?'hidden':''}><div class="tab-photo">${img(x[1],x[0])}<span>${I('scan')} A CLOSER PERSPECTIVE</span></div><div class="tab-copy"><h3>${x[2]}</h3><p>${x[3]}</p><ul>${x[4].map(t=>`<li>${I('check')}${t}</li>`).join('')}</ul>${btn('contact.html','Talk about your space','outline')}</div></div>`).join('')}</div>`}
const serviceContent={extract:{intro:'Make room for the next step.',text:'A clear description helps an independent provider understand the space before an assessment.',cards:[['Affected rooms','Describe connected rooms, levels and where water is visible.','house'],['Source & timing','Share what you know about the source and when you noticed it.','clock-3'],['Access & layout','Include entrances, stairs and equipment access.','door-open'],['Contents & finishes','Note furniture and the materials that have been affected.','armchair']],panels:[['r8-perspective-1','Below ground','A different level of detail. Include layout, drainage and access.'],['r8-perspective-2','Along the hallway','Describe connected rooms, thresholds and the visible route of the water.'],['r8-perspective-3','Living areas','Consider the connected rooms and materials beneath the water.']],gallery:[['service-4','Follow the water','Include changes beyond the main affected area.'],['service-13','Across the levels','Stairs and thresholds help describe the route water took.'],['service-14','Equipment & access','Ask how the setup will suit your property.'],['editorial-17','A clearer space','Discuss what happens after extraction.']],faqPhoto:'extra-extract',questions:[['What follows water extraction?','Ask about the assessment of retained moisture, the condition of materials and any further drying or repair that may be needed.'],['What affects the quote?','Access, water conditions, the affected area and the agreed scope can all influence a provider’s quotation.'],['What should I describe first?','Begin with the affected room or level, the visible extent of water, timing and anything known about the source.']]},dry:{intro:'There is more beneath the finish.',text:'Materials and moisture shape the conversation. Explore the questions behind a considered drying plan.',cards:[['Material assessment','Ask what surfaces and concealed areas will be checked.','scan-line'],['Equipment planning','Discuss how the setup relates to the assessed conditions.','fan'],['Recorded progress','Understand how the provider documents changes.','chart-no-axes-combined'],['The next stage','Ask what evidence is used before recommending repairs.','clipboard-check']],panels:[['r8-perspective-4','Connected spaces','Discuss adjoining rooms, materials and the extent of the assessment.'],['r8-perspective-5','Reading the space','Ask how readings are interpreted for the material.'],['r8-perspective-6','Controlled airflow','Discuss equipment, placement and access during the work.']],gallery:[['service-8','Masonry in focus','Different materials call for different questions.'],['service-15','Above the ceiling','Concealed areas can be part of the assessment.'],['service-16','A planned setup','Agree how equipment and the space will be managed.'],['editorial-18','Progress with context','Ask what will be recorded and explained.']],faqPhoto:'extra-dry',questions:[['Does dry to the touch mean the work is complete?','A surface appearance alone is not a property-specific assessment. Ask how the provider evaluates moisture within the relevant materials.'],['How long will drying take?','The conditions and materials vary. Ask the provider for an assessed plan and how it may change as progress is recorded.'],['What should I ask before repairs begin?','Ask how completion is assessed and what documentation supports the recommendation to move into repair.']]},restore:{intro:'Bring the details together.',text:'A good restoration conversation considers both the damage and the space it belongs to.',cards:[['Walls & surfaces','Discuss preparation, texture and the finished appearance.','paint-roller'],['Floors & junctions','Consider thresholds and how repaired areas meet existing finishes.','layers'],['Frames & surrounds','Include seals, sills and adjacent surfaces.','panels-top-left'],['A written scope','Agree preparation, repairs, finishing and exclusions.','file-check']],panels:[['r8-perspective-7','Around the window','Bring the frame and the surrounding finish into the same conversation.'],['r8-perspective-8','Underfoot','Discuss repairability, matching and transitions.'],['r8-perspective-9','A considered finish','Surface preparation and texture matter to the result.']],gallery:[['service-18','A new outlook','Restore the details around the light.'],['extra-restore-1','At the threshold','Small transitions make the room feel complete.'],['extra-restore-2','The final texture','Agree the finish before the work begins.'],['extra-restore-3','Room to begin again','Think about the whole space, not only the affected patch.']],faqPhoto:'extra-restore',questions:[['Can the original materials be retained?','That depends on their assessed condition. Discuss repair and replacement options with your chosen provider.'],['When should restoration begin?','Ask the provider how the source and moisture conditions have been addressed before repairs or finishes are applied.'],['Can I match the existing finish?','Share details of the original materials and ask about samples, matching limitations and how adjacent areas will be treated.']]}};
function horizontal(panels){return `<div class="horizontal-accordion">${panels.map(([im,t,p],i)=>`<button class="accordion-panel ${i===0?'active':''}" aria-expanded="${i===0}">${img(im,t)}<span class="panel-label"><strong>${t}</strong><small>${p}</small></span><b>${I('plus')}</b></button>`).join('')}</div>`}
function servicePage(s){const d=serviceContent[s.key];const first=s.key==='extract'?extractOverlap():s.key==='dry'?dryMosaic():restoreBrush();const second=s.key==='extract'?extractStrip():s.key==='dry'?dryFrame():restoreOrganic();const third=s.key==='extract'?extractSlider():s.key==='dry'?dryTabs():restoreGallery();const fourth=s.key==='extract'?extractNotches():s.key==='dry'?dryDiscussion():restoreFrame();const fifth=s.key==='extract'?extractProcess():s.key==='dry'?dryPerspectives():restoreLayers();return hero(s.id)+water()+first+section('perspectives','perspective-section mist',heading('A closer perspective.','Explore the details that help describe your space.')+horizontal(d.panels))+second+section('before-after','comparison-section',compare(s.key))+third+(s.key==='restore'?section('materials','materials-section',heading('Materials. In context.','Explore window frame details when discussing water-related repairs.',true)+tabs('materials',[['Timber','extra-timber','Natural character. Considered repair.','Discuss swelling, staining, joints and the surrounding finishes. Ask which parts can be retained after assessment.',['Grain and texture','Repair options','Surface finish']],['uPVC','service-11','Look beyond the profile.','Include seals, drainage paths and adjoining wall finishes. A non-porous frame does not describe the condition of the surrounding space.',['Seals and joints','Drainage paths','Wall junctions']],['Aluminium','service-12','Slim lines. Precise details.','Discuss the condition of joints, seals and adjacent materials before agreeing the scope of repairs.',['Frame condition','Seal detailing','Surrounding finishes']]])):'')+fourth+newSections(s.key).slice(0,3).join('')+fifth+newSections(s.key).slice(3).join('')+section('questions','faq-section',`<div class="faq-layout"><div class="faq-editorial"><h2 class="reveal">Before you begin.</h2><p>Bring a little more clarity to the next conversation.</p>${img(d.faqPhoto,'A specialist at work in a distinctive interior')}</div>${faq(d.questions.concat([['Who agrees the price and scope?','You and your chosen independent provider. Confirm assessment charges, exclusions and the written scope before proceeding.']]))}</div>`)+cta(s.key==='dry'?'surveyor':s.key==='restore'?'restorer':'extractor',s.key==='restore'?'Make space for a fresh start.':'Your next step starts here.')+marquee()}
function form(){return `<form id="contact-form" action="contact.php" method="post"><h2>A few useful details.</h2><p>Tell us what happened and what you would like to understand.</p><div class="form-row"><label>Your name<input name="name" required minlength="2" maxlength="100" placeholder="Full name" autocomplete="name"></label><label>Email address<input type="email" name="email" required maxlength="254" placeholder="you@example.com" autocomplete="email"></label></div><div class="form-row"><label>Service<select name="service" required><option value="">Choose a service</option>${services.map(s=>`<option value="${s.id}" ${new URLSearchParams(location.search).get('service')===s.id?'selected':''}>${s.name}</option>`).join('')}</select></label><label>Affected space<input name="space" maxlength="150" placeholder="e.g. ground floor"></label></div><label>Your message<textarea name="message" rows="4" required minlength="10" maxlength="5000" placeholder="The space, what you noticed and when it happened…"></textarea></label><label class="honeypot" aria-hidden="true">Website<input name="website_check" tabindex="-1" autocomplete="off"></label><label class="consent"><input type="checkbox" name="privacy_consent" value="1" required><span>I have read the <a href="privacy.html">Privacy Policy</a> and agree to the use of my details to respond to this enquiry.</span></label><button type="submit" class="btn"><span>Send my enquiry</span>${I('send')}</button><p class="form-status" role="status" aria-live="polite"></p></form>`}
function contact(){return hero('contact')+water()+section('enquiry','contact-section',`<div class="contact-grid"><aside class="contact-aside"><h2 class="reveal">A conversation.<br>With context.</h2><p>Your description helps give the next step a little more direction.</p><div class="contact-email">${I('mail')}<span>Write to us<a href="mailto:${esc(C.email)}">${esc(C.email)}</a></span></div><div class="contact-steps"><div>${I('notebook-pen')}<span><strong>Describe the space</strong><small>Include the rooms and affected materials.</small></span></div><div>${I('messages-square')}<span><strong>Share your questions</strong><small>Tell us what you would like to understand.</small></span></div><div>${I('handshake')}<span><strong>Choose independently</strong><small>Agree scope and pricing directly with a provider.</small></span></div></div><p class="disclaimer">${esc(C.disclaimer)}</p></aside>${form()}</div>`)+section('contact-questions','contact-faq mist',`<div class="contact-question-grid"><div><h2 class="reveal">A little more clarity.</h2><p>Know what to expect from an enquiry.</p>${art('contact-surveyor')}</div>${faq([['Does an enquiry book a contractor?','No. Sending an enquiry is a first conversation. Availability, assessment and work must be agreed directly with a provider.'],['Can you quote from my message?','We do not set provider prices. Ask your chosen provider about the assessment and a written quotation.'],['How is my information used?','Your details are used to review and respond to your enquiry. Read the Privacy Policy for more information.']])}</div>`)}
function legal(){const data={privacy:['Your privacy.','A clear view of how enquiry information is handled.',[['What you share','An enquiry includes your name, email, selected service, affected space and message. Please avoid including sensitive personal information.'],['How information is used','Your details are used to review and respond to your enquiry. Any proposed onward sharing with an independent provider should be explained before it occurs. Enquiry information is not sold.'],['Service providers','Website hosting and email providers may process information needed to run this website and deliver messages. Your chosen restoration provider has its own privacy practices.'],['Retention and requests','Information should be retained only as needed to handle the enquiry and applicable obligations. Contact us to request access, correction or deletion.']]],terms:['Clear terms.','Understand the platform before taking the next step.',[['Our role',C.disclaimer],['Your chosen provider','Confirm suitability, credentials, availability, scope and terms directly with the provider. The platform does not carry out work, set provider prices or guarantee outcomes.'],['Information and imagery','Content is general information, not an assessment of your property. Generated imagery and comparisons illustrate possible situations, not completed client projects or specific members of a provider network.'],['Enquiries and agreements','Sending an enquiry does not create a restoration contract. Review a written quotation, the scope, exclusions and payment terms directly with your provider.']]],cookies:['Your choices.','A small amount of storage. A clear explanation.',[['Essential storage','This website stores your cookie choice in local storage so that the notice does not appear on every page. This is browser storage, not a tracking cookie.'],['No tracking installed','No analytics or advertising trackers are installed. Choosing Accept does not enable additional tracking.'],['Change your preference','Use Cookie settings in the footer to reopen the notice. You can also clear site data using your browser settings.'],['External services','If you leave this website, the destination service has its own privacy and storage practices.']]]}[route];const extra={privacy:[['Messages and replies','The enquiry form requests your name, email address, selected service, affected space and message. Required fields help us understand the request and reply to the address you provide.','The message is intended for property and service context. Please avoid sending identification documents, financial details or private information about other people.'],['Delivery and technical data','The form sends its contents to the website’s configured email recipient. Hosting and email systems may process technical information needed to receive, deliver and protect those messages.','If delivery fails, the website displays an error. You may contact the email address shown on this page instead. A successful on-screen response confirms server acceptance, not a provider booking.'],['Your requests','You can contact us to ask about an enquiry, correct information you supplied or request its deletion. Include enough context to identify the relevant conversation.','For access or deletion requests, we may need to confirm that the request relates to your information. Applicable requirements and any necessary record retention are considered when responding.'],['Sharing and your provider','Sending an enquiry does not authorise every independent provider to contact you. Any proposed onward sharing should be explained in the context of your request.','If you contact or appoint a provider directly, its own privacy notice governs information you share with that business. Ask the provider about its handling of assessment records and photographs.']],terms:[['Scope and suitability','Website content helps you prepare questions about water extraction, drying and repairs. It does not determine the condition of a property or prescribe a technical treatment.','A provider’s assessment is needed to understand the specific circumstances, materials, access and scope. Discuss any uncertainty before agreeing to work.'],['Quotes and agreements','Request a written quotation that explains the proposed work, assessment charges, exclusions and any further costs that may arise. Prices and availability are set by independent providers.','An enquiry through this website does not reserve an appointment or create a restoration contract. Any booking, payment, cancellation and warranty arrangements are agreed directly with the chosen provider.'],['Responsible use','Provide an accurate description to the best of your knowledge and use an email address at which you can receive replies. Do not submit abusive messages, unsolicited advertising or information you have no right to share.','Automated misuse or submissions that interfere with the website may be rejected. Form validation and submission limits help maintain the enquiry service.'],['Availability and changes','The website may be updated as services, content and contact details change. Temporary interruptions can occur, including when email delivery or hosting is unavailable.','If a form submission fails, follow the displayed message or contact the published email address. Do not treat an unconfirmed submission as an accepted booking.']],cookies:[['Preference storage','The key afterwater-consent stores your choice in this browser’s local storage. Its value records whether you selected Accept or Essential only.','The preference remains until you clear site data or change it through Cookie settings in the footer. It does not create an account or follow you to another device.'],['Form session','On a PHP-enabled host, the contact handler can start a server session to limit rapid repeated submissions. This session stores the time of the most recent submission attempt.','The browser may receive a session cookie for that purpose. Its duration and attributes depend on the hosting configuration; it is separate from the saved cookie preference.'],['Search and interactions','Website search filters the built-in list of pages and sections in your browser. Entering a search query does not submit the enquiry form.','Image sliders, tabs and comparison controls work within the page. No advertising or analytics tracker is enabled by the Accept button.'],['Browser controls','You can review or clear local storage and cookies in your browser’s site settings. Clearing the saved preference makes the notice appear again.','Blocking storage may prevent your choice from being remembered. The pages remain available, while the behaviour of form sessions depends on the host and browser settings.']]};data[2]=data[2].concat(extra[route]);return section('legal-intro','legal-hero',`<div><span>${esc(C.legalName)}</span><h1>${data[0]}</h1><p>${data[1]}</p></div>${art('drops')}`)+section('legal-content','legal-content',`<div class="legal-grid"><nav>${data[2].map(([t],i)=>`<a href="#policy-${i}">${t}${I('arrow-up-right')}</a>`).join('')}</nav><div>${data[2].map(([t,p,p2],i)=>`<article id="policy-${i}"><h2>${t}</h2><p>${esc(p)}</p>${p2?`<p>${esc(p2)}</p>`:''}</article>`).join('')}<div class="legal-contact">${I('mail')}<div><strong>Questions? Let’s talk.</strong><a href="mailto:${esc(C.email)}">${esc(C.email)}</a></div></div>${route==='terms'?`<article id="credits"><h2>Icon credits</h2><p>Themed icons by <a href="https://www.flaticon.com/authors/konkapp">Konkapp</a>, <a href="https://www.flaticon.com/authors/magnific">Magnific</a>, <a href="https://www.flaticon.com/authors/ayub-irawan">Ayub Irawan</a> and <a href="https://www.flaticon.com/authors/pixelmeetup">Pixelmeetup</a> from <a href="https://www.flaticon.com/">Flaticon</a>. Interface icons: Lucide.</p></article>`:''}</div></div>`)}
const R=(g,n,alt='')=>img(`v5-${g}-${n}`,alt);
const tickItems=items=>`<ul class="r-ticks">${items.map(t=>`<li>${I('check')}${t}</li>`).join('')}</ul>`;
function refSection(id,kind,content){return section(id,'ref-section '+kind,content)}
function refServices(){const descriptions=['Standing water needs a property-specific assessment. Share the source, affected rooms and access so a provider can discuss the right removal approach.','A dry-looking finish can hide retained moisture. Bring materials, construction and measurement questions into the conversation before repair begins.','From damaged plaster to flooring and window details. Discuss what can be retained, how finishes will match and what belongs in the written scope.'];return refSection('service-explorer','r-service-explorer',heading('The right help. At the right stage.','Three connected services. Explore where your space fits.')+`<div class="r-service-accordion">${services.map((s,i)=>`<article class="r-service-item ${i===0?'selected':''}"><button class="r-service-toggle" aria-expanded="${i===0}" aria-controls="service-content-${i}"><span>${I(s.icon)}</span><strong>${s.name}</strong><b>${I('plus')}</b></button><p class="r-service-summary">${descriptions[i]}</p><div class="r-service-content" id="service-content-${i}"><div><a href="${s.id}.html" class="r-text-link">Explore ${s.name.toLowerCase()} ${I('arrow-up-right')}</a></div></div></article>`).join('')}</div><div class="r-photo-pair"><figure>${img('r8-explore-1','Water extraction in a slate-floored hallway')}<figcaption>From standing water</figcaption></figure><figure>${img('r8-explore-2','Drying equipment in a vaulted sunroom')}<figcaption>To the next assessment</figcaption></figure></div>`)}
function homeCircle(){return refSection('a-personal-perspective','r-circle-section',`<div class="r-split"><div class="r-copy"><h2>A home.<br>Not just a project.</h2><p class="r-lead">The details you care about belong in the first conversation.</p><p>Tell a provider how you use the rooms, which materials matter to you and what changed after the water arrived. A more complete brief makes the next step easier to understand.</p><div class="r-two-notes"><span>${I('house')} Your space, in context</span><span>${I('messages-square')} Your questions, heard</span></div>${tickItems(['Describe the visible changes','Explain what you hope to preserve'])}${btn('contact.html','Start with your space','outline')}</div><div class="r-circle-art"><figure class="r-main-circle">${R('home',3,'Refined oak flooring beside tall steel windows')}</figure><figure class="r-small-circle">${R('home',4,'Building surveyor considering the details of a townhouse')}</figure><button class="r-circle-trigger" aria-label="Show what to include in an enquiry" data-circle-toggle>${I('plus')}</button><div class="r-circle-note" hidden><strong>A useful first description</strong><p>The room, the material, when it changed and what you would like to understand.</p></div></div></div>`)}
function pillProcess(){return refSection('a-clear-beginning','r-pill-process mist',heading('A clear beginning.','Good context makes room for better decisions.',true)+`<div class="r-pill-grid">${[['messages-square','Describe the change','Start with the room, the timing and what you noticed. A clear description gives the enquiry a practical starting point.'],['scan-line','Discuss the findings','Ask how an independent provider will assess the space and explain the condition of the affected materials.'],['clipboard-check','Agree the next step','Compare a written scope, costs and exclusions. Choose your provider and agree the work directly.']].map(([icon,t,p],i)=>`<article tabindex="0" class="${i===1?'featured':''}"><span class="r-orbit-icon">${I(icon)}</span><div><h3>${t}</h3><p>${p}</p></div></article>`).join('')}</div>`)}
function carouselControls(id){return `<div class="slider-controls"><button class="prev icon-btn" data-slider="${id}" aria-label="Previous slide">${I('arrow-left')}</button><div class="slider-progress" aria-hidden="true"><span></span></div><button class="next icon-btn" data-slider="${id}" aria-label="Next slide">${I('arrow-right')}</button></div>`}
function homeVoices(){return refSection('questions-worth-asking','r-voices',heading('Make the conversation count.','Useful questions for your independent provider.',true)+`<div class="slider-shell r-voice-shell"><div class="swiper" id="home-voices"><div class="swiper-wrapper">${[[5,'What does the assessment cover?','Ask which rooms and materials will be reviewed, what information will be recorded and whether there is an assessment charge. Clarify how the findings will help you decide what happens next.','Before an assessment'],[6,'How will the findings be explained?','Request a clear account of the visible changes and readings, including what remains uncertain and what needs further investigation. Ask for a record you can refer to when comparing the proposed next steps.','When reviewing findings'],[7,'What can be retained?','Discuss sound materials, repair options and the effect of matching new finishes to the rest of your home. Request a clear explanation of preparation, samples and any limitations before agreeing the finish.','Before agreeing repairs'],[11,'What belongs in the written scope?','Ask for equipment, visits, preparation and finishing to be itemised. Confirm exclusions, access arrangements and how any changes will be agreed before work begins.','Before making a decision']].map(([n,t,p,l])=>`<article class="swiper-slide r-voice"><div class="r-voice-photo">${n===11?img('extra-assessment','Professional reviewing an assessment'):R('home',n,'Illustrative professional assessment perspective')}</div><div><span class="r-quote-mark">${I('quote')}</span><h3>${t}</h3><p>${p}</p><span class="r-caption">${l}</span></div></article>`).join('')}</div></div>${carouselControls('home-voices')}</div>`)}
function homeCollage(){return refSection('beyond-the-obvious','r-collage-section',`<div class="r-split"><div class="r-copy"><h2>Look beyond<br>the obvious.</h2><p class="r-lead">Water changes more than the surface you first see.</p><p>Include ceilings, thresholds, stairs and adjoining rooms when describing the event. Explain which changes are new and which details you are unsure about.</p><div class="r-feature-pair"><article>${I('scan')}<strong>Follow the signs</strong><p>Share visible staining, movement and changes to finishes.</p></article><article>${I('layers')}<strong>Consider the layers</strong><p>Ask how concealed materials will be assessed.</p></article></div></div><div class="r-triple-photo"><figure>${R('home',8,'Water staining around a skylight')}</figure><figure>${R('home',9,'Careful work on a walnut staircase')}</figure><figure>${R('home',10,'Restored kitchen with slate flooring')}</figure></div></div>`)}
function extractOverlap(){return refSection('extraction-in-context','r-offset-section',`<div class="r-split"><div class="r-offset-photos"><figure>${R('extract',1,'Extraction setup in a converted stone cellar')}</figure><figure>${R('extract',2,'Careful water extraction from limestone')}</figure><span class="r-frame-line" aria-hidden="true"></span></div><div class="r-copy"><h2>A clearer space.<br>A considered start.</h2><p class="r-lead">Every extraction enquiry begins with the property.</p><p>Describe the affected level, the source if known and the connected rooms. Include entrances, stairs and any limitations on access that may influence the assessment.</p><div class="r-quality-grid">${tickItems(['Source and timing','Affected materials','Equipment access'])}<div><span>Standing water removal</span><span>Follow-up moisture checks</span></div></div><div class="r-framed-statement">Discuss what follows extraction before agreeing the scope.</div></div></div>`)}
function extractStrip(){return refSection('practical-details','r-detail-strip mist',`<div class="r-strip-grid">${[['door-open','Plan the access','Describe entrances, stairs and the route to the affected room. Ask how unaffected areas will be protected.'],['armchair','Include the contents','Mention furniture, storage and finishes in contact with water. Clarify what is included in the proposed scope.'],['file-check','Keep a clear record','Request findings and recommendations in writing. Ask which observations lead to the next stage.']].map(([i,t,p])=>`<article>${I(i)}<div><h3>${t}</h3><p>${p}</p><a href="contact.html?service=water-extraction">Discuss the details</a></div></article>`).join('')}</div>`)}
function extractSlider(){return refSection('water-perspectives','r-dark-slider graphite',`<div class="r-side-slider"><div class="r-copy"><h2>Water takes<br>different paths.</h2><p>Connected rooms and changes in level help explain the extent of an event. Share the layout as well as the visible water.</p>${btn('contact.html?service=water-extraction','Describe the setting')}</div><div class="slider-shell"><div class="swiper" id="extraction-settings"><div class="swiper-wrapper">${[[3,'Garden-level rooms','Include courtyard access, adjoining spaces and floor finishes.'],[4,'Working spaces','Discuss contents, equipment access and the use of the room.'],[5,'Shared entrances','Describe thresholds, connected corridors and access arrangements.'],[6,'Lower-level workshops','Mention drainage points, stored materials and the visible extent.']].map(([n,t,p])=>`<article class="swiper-slide r-scene-card">${R('extract',n,t)}<div>${I('waves')}<h3>${t}</h3><p>${p}</p><a href="contact.html?service=water-extraction">Include in your enquiry ${I('arrow-up-right')}</a></div></article>`).join('')}</div></div>${carouselControls('extraction-settings')}</div></div>`)}
function extractNotches(){return refSection('removal-details','r-notch-section',heading('Details that shape the scope.','A better description gives the assessment more context.')+`<div class="r-notch-grid">${[[7,'Below the entrance','Explain changes in level and how the affected area can be reached.','move-down'],[8,'Across the threshold','Describe connected finishes and where water is visible.','scan-line'],[9,'Around the source','Include the appliance, pipework or known point of entry.','droplets']].map(([n,t,p,i])=>`<article class="r-notch-card"><div class="r-notch-photo">${R('extract',n,t)}</div><span class="r-notch-icon">${I(i)}</span><div class="r-notch-copy"><h3>${t}</h3><p>${p}</p>${btn('contact.html?service=water-extraction','Discuss this detail','white-btn')}</div></article>`).join('')}</div>`)}
function extractProcess(){return refSection('after-removal','r-simple-process',heading('After the water. What follows?','Ask how the next stage will be assessed.',true)+`<div class="r-simple-grid">${[['scan-line','Review the materials','Ask which materials retain moisture and what further assessment is included.'],['fan','Discuss drying','Clarify any proposed equipment, monitoring and changes to room access.'],['paint-roller','Consider repair','Discuss what evidence supports the move from drying to repairs and finishes.']].map(([i,t,p])=>`<article><span>${I(i)}</span><h3>${t}</h3><p>${p}</p></article>`).join('')}</div>`)}
function dryMosaic(){return refSection('materials-and-moisture','r-mosaic-section',`<div class="r-split"><div class="r-copy"><h2>Every material.<br>Part of the picture.</h2><p class="r-lead">Drying is a conversation about construction, not just air.</p><p>Timber, plaster and masonry respond differently. Explain the build-up of your space where known and ask how the assessment will consider visible and concealed layers.</p><div class="r-inline-topics"><span>${I('layers')} Materials</span><span>${I('scan-line')} Readings</span><span>${I('wind')} Airflow</span></div>${btn('contact.html?service=structural-drying','Discuss your materials','outline')}</div><div class="r-staggered-mosaic">${[1,2,3,4].map((n,i)=>`<figure>${R('dry',n,['Drying a timber room','Checking moisture at a plaster reveal','Drying equipment beside terrazzo stairs','Assessment of an exposed brick wall'][i])}</figure>`).join('')}</div></div>`)}
function dryFrame(){return refSection('a-room-wide-view','r-frame-section',`<div class="r-split"><div class="r-tall-frame"><figure>${R('dry',5,'Drying equipment in an oak staircase atrium')}</figure><figure>${R('dry',6,'Technician assessing a window reveal')}</figure><span class="r-image-badge">${I('scan-line')} A room-wide view</span></div><div class="r-copy"><h2>See the room.<br>Understand the layers.</h2><p class="r-lead">The layout gives each observation its context.</p><p>Ask how connected spaces, cavities and finishes affect the assessment. Discuss whether access is needed behind a surface and how the findings will be explained.</p>${btn('contact.html?service=structural-drying','Prepare your questions')}<div class="r-bottom-facts"><div><strong>Locate</strong><span>Where readings are taken</span></div><div><strong>Interpret</strong><span>What findings can show</span></div><div><strong>Review</strong><span>What changes the plan</span></div></div></div>`)}
function dryTabs(){return refSection('drying-observations','r-vertical-tabs mist',`<div class="r-observation-head">${heading('Observations with meaning.','Explore the questions behind a drying plan.')}</div><div class="r-observation" data-observation><div class="r-observation-tabs" role="tablist" aria-label="Drying observations" aria-orientation="vertical">${[['Read the material','Understand the measurement method.'],['Read the space','Place findings in the room’s context.'],['Read the progress','Connect observations to the next step.']].map(([t,p],i)=>`<button role="tab" aria-selected="${i===0}" aria-controls="observation-${i}" id="observe-tab-${i}" data-observe="${i}"><span>${I(['scan-line','house','chart-no-axes-combined'][i])}</span><strong>${t}<small>${p}</small></strong>${I('plus')}</button>`).join('')}</div><div class="r-observation-content">${[[7,'Look at the method.','Ask which method is being used, where it is suitable and what the results can and cannot tell you.',['Material and finish','Measurement location','Method limitations']],[8,'Connect the findings.','Ask how readings relate to the construction and adjacent areas. A single observation does not describe the whole room.',['Connected spaces','Concealed layers','Further assessment']],[9,'Follow the changes.','Discuss how repeat checks inform the plan. Ask what supports adjustments and when the next stage can be considered.',['Recorded progress','Equipment adjustments','Completion criteria']]].map(([n,t,p,ls],i)=>`<div class="r-observation-panel" role="tabpanel" id="observation-${i}" aria-labelledby="observe-tab-${i}" ${i?'hidden':''}><figure>${R('dry',n,t)}</figure><div><h3>${t}</h3><p>${p}</p>${tickItems(ls)}</div></div>`).join('')}</div></div>`)}
function dryDiscussion(){return refSection('the-assessment-desk','r-discussion-section',`<div class="r-discussion"><figure>${R('dry',10,'Drying specialist considering an assessment')}</figure><div><h2>Bring better questions.</h2><p>Clarify the practical details before agreeing to a plan.</p><div class="r-discussion-cards">${[['What is monitored?','Ask which locations and materials are checked, how often and how the results are recorded.','scan-line'],['What is included?','Discuss equipment, visits, access arrangements and any exclusions in the written quotation.','clipboard-list']].map(([t,p,i])=>`<article>${I(i)}<h3>${t}</h3><p>${p}</p><span>FOR YOUR PROVIDER</span></article>`).join('')}</div></div></div>`)}
function dryPerspectives(){return refSection('specialist-perspectives','r-portrait-section',heading('Different expertise. One space.','Questions to discuss with the professionals involved.',true)+`<div class="r-portrait-grid">${[[11,'Material assessment','How are the affected layers identified?','scan'],[12,'Equipment planning','How will the setup suit this room?','fan'],[13,'Progress review','What supports the next decision?','clipboard-check']].map(([n,t,p,i])=>`<article class="r-portrait-card" tabindex="0"><figure>${R('dry',n,t)}</figure><div><span>${I(i)}</span><h3>${t}</h3><p>${p}</p></div></article>`).join('')}</div>`)}
function restoreBrush(){return refSection('a-considered-repair','r-brush-section',`<div class="r-split"><div class="r-brush-photo">${R('restore',1,'Craftswoman repairing a plaster wall')}<span aria-hidden="true"></span></div><div class="r-copy"><h2>Restore the details<br>that make it yours.</h2><p class="r-lead">A room has character worth considering.</p><p>Ask which materials can be retained, where preparation is needed and how repaired areas will meet existing finishes. Discuss the visible result as well as the work beneath it.</p><p>Samples, a written scope and clear handover details help put expectations into words before work begins.</p>${btn('contact.html?service=damage-restoration','Talk about your priorities','outline')}</div></div>`)}
function restoreOrganic(){return refSection('character-and-care','r-organic-section mist',`<div class="r-split"><div class="r-organic-photo"><figure>${R('restore',2,'Carpenter reviewing a finish sample')}</figure><figure>${R('restore',3,'Restored parquet in a sunlit living room')}</figure><span aria-hidden="true"></span></div><div class="r-copy"><h2>Character.<br>Carefully considered.</h2><p>Share the finishes you would like to preserve and the details that matter most. A provider can assess condition and explain the available repair options.</p>${tickItems(['Retain sound materials','Discuss matching and transitions','Review samples in the room','Agree preparation and finishing'])}<div class="r-soft-note">${I('paintbrush')} Small finishing decisions shape the whole room.</div>${btn('contact.html?service=damage-restoration','Explore your options')}</div></div>`)}
function restoreGallery(){return refSection('finish-perspectives','r-tall-gallery',heading('A different finish. A fresh outlook.','Illustrative spaces to help frame your preferences.',true)+`<div class="r-gallery-grid">${[[4,'At the staircase','Junctions & handrails'],[5,'Around the window','Reveals & seals'],[6,'Across the kitchen','Flooring & cabinetry'],[7,'Inside the living room','Walls & woodwork']].map(([n,t,p])=>`<article tabindex="0">${R('restore',n,t)}<div><span>${p}</span><h3>${t}</h3><a href="contact.html?service=damage-restoration">Discuss the finish ${I('arrow-up-right')}</a></div></article>`).join('')}</div>`)}
function restoreFrame(){return refSection('the-repair-conversation','r-framed-team',`<div class="r-team-top"><div class="r-copy"><h2>Bring the details together.</h2><p>Ask how preparation, repair and finishing connect. Agree responsibilities, exclusions and the checks that belong at handover.</p>${btn('contact.html?service=damage-restoration','Prepare your enquiry','outline')}</div><figure>${R('restore',8,'Professionals reviewing repair samples')}<span>${I('messages-square')} An informed conversation</span></figure></div><div class="r-team-features">${[['layers','Prepare the surface','Discuss condition, retained layers and preparation included in the scope.'],['paint-roller','Agree the finish','Review colour, texture and transitions to the existing room.'],['clipboard-check','Review the details','Ask which checks and finishing items are included at handover.']].map(([i,t,p])=>`<article><span>${I(i)}</span><h3>${t}</h3><p>${p}</p></article>`).join('')}</div>`)}
function restoreLayers(){return refSection('where-finishes-meet','r-layered-section',`<div class="r-split"><div class="r-layered-photo"><figure>${R('restore',9,'Finished oak flooring at a doorway')}</figure><figure>${R('restore',10,'Repairing a window reveal')}</figure></div><div class="r-copy"><h2>Where finishes meet.</h2><p>Doorways, frames and floor edges deserve a place in the scope. Discuss how a repaired area will connect with materials that remain.</p>${tickItems(['Floor-to-wall transitions','Window and door reveals','Tone, grain and texture','Preparation at the edges'])}<blockquote>A sample makes the conversation more specific. Ask to see the finish in the room’s own light.</blockquote>${btn('contact.html?service=damage-restoration','Discuss the junctions','outline')}</div></div>`)}

