const revealTargets=$$('h1,h2,h3');revealTargets.forEach(x=>x.classList.remove('reveal','liquid-title'));if('IntersectionObserver' in window&&!reduce){const titleObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting&&e.target.getBoundingClientRect().height){const h=e.target;titleObserver.unobserve(h);const walker=document.createTreeWalker(h,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);const total=nodes.reduce((n,t)=>n+t.textContent.length,0);let index=0;nodes.forEach(node=>{const fragment=document.createDocumentFragment();for(const char of node.textContent){const span=document.createElement('span');span.className='type-char';span.textContent=char;fragment.append(span);if(char.trim())span.animate([{opacity:.12},{opacity:1}],{duration:260,delay:index*Math.min(24,700/Math.max(total,1)),fill:'backwards',easing:'ease-out'});index++}node.replaceWith(fragment)})}}),{threshold:.08});revealTargets.forEach(x=>titleObserver.observe(x))}$$('.reveal').forEach(x=>x.classList.add('in-view'));
