const f=$('#contact-form');if(f)f.onsubmit=async e=>{e.preventDefault();if(!f.reportValidity()||f.dataset.busy)return;f.dataset.busy='1';const b=$('button[type="submit"]',f),s=$('.form-status');b.disabled=true;s.textContent='Sending your enquiry…';try{const r=await fetch(C.contactEndpoint,{method:'POST',body:new FormData(f),headers:{Accept:'application/json'}});const d=await r.json();if(!r.ok||d.success!==true)throw Error(d.message);s.textContent=C.formSuccessMessage;f.reset()}catch(e){s.textContent='Your enquiry could not be sent. Please use email or try again on the configured PHP host.'}finally{delete f.dataset.busy;b.disabled=false}};
