$$('[data-observation]').forEach(w=>{let busy=false;$$('[data-observe]',w).forEach(b=>b.onclick=()=>{if(b.getAttribute('aria-selected')==='true'||busy)return;busy=true;const panels=$$('.r-observation-panel',w),old=panels.find(p=>!p.hidden),next=panels[+b.dataset.observe];const swap=()=>{old.hidden=true;next.hidden=false;$$('[data-observe]',w).forEach(x=>x.setAttribute('aria-selected',String(x===b)));if(!reduce)next.animate([{opacity:0,transform:'translateY(7px)'},{opacity:1,transform:'none'}],{duration:400,easing:'ease-out'});busy=false};if(reduce)swap();else old.animate([{opacity:1},{opacity:0}],{duration:180}).onfinish=swap})});
