$$('[data-story]').forEach(w=>{const buttons=$$('[role=tab]',w),panels=$$('[role=tabpanel]',w);function activate(i){buttons.forEach((b,n)=>{b.setAttribute('aria-selected',n===i);b.tabIndex=n===i?0:-1;panels[n].hidden=n!==i});if(!reduce)panels[i].animate([{opacity:.3,translate:'0 6px'},{opacity:1,translate:'0 0'}],{duration:480,easing:'ease-out'})}buttons.forEach((b,i)=>{b.tabIndex=i===0?0:-1;b.onclick=()=>activate(i);b.onkeydown=e=>{if(['ArrowRight','ArrowLeft','ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();e.stopPropagation();const n=e.key==='Home'?0:e.key==='End'?buttons.length-1:(i+(e.key==='ArrowRight'||e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length;activate(n);buttons[n].focus()}}})});
