$$('.n-ready').forEach(w=>{let motion;const number=$('[data-ready-number]',w);$$('[data-ready]',w).forEach(c=>c.onchange=()=>{const target=30+$$('[data-ready]:checked',w).length*35,start=Number(number.textContent);$('.n-ready-track span',w).style.width=target+'%';if(motion)cancelAnimationFrame(motion);if(reduce){number.textContent=target;return}const beginning=performance.now();const tick=now=>{const p=Math.min(1,(now-beginning)/850);number.textContent=Math.round(start+(target-start)*(1-Math.pow(1-p,3)));if(p<1)motion=requestAnimationFrame(tick)};motion=requestAnimationFrame(tick)})});
if('IntersectionObserver' in window&&!reduce){const mosaicObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){mosaicObserver.unobserve(e.target);const nodes=[...e.target.children].filter(x=>!x.classList.contains('mosaic-square'));nodes.forEach((x,i)=>x.animate([{opacity:.15,translate:`${i%2?12:-12}px 16px`,scale:'.97'},{opacity:1,translate:'0 0',scale:'1'}],{duration:750,delay:i*115,fill:'backwards',easing:'cubic-bezier(.16,1,.3,1)'}))}}),{threshold:.08});$$('#about .mosaic,#beyond-the-obvious .r-triple-photo,[data-mosaic],.r-staggered-mosaic,.r-gallery-grid,.takeover').forEach(x=>mosaicObserver.observe(x))}
